from manim import *

class OneSidedLimitAnimation(Scene):
    def construct(self):
        axes = Axes(x_range=[-2, 2], y_range=[-2, 2], axis_config={"include_numbers": True}).scale(1.2)

        def f(x):
            if x < 0:
                return -1
            elif x > 0:
                return 1
            else:
                return 0

        graph = axes.plot(lambda x: f(x), color=BLUE, discontinuities=[0], dt=0.01)

        left_dot = Dot(axes.coords_to_point(0, -1), color=RED)
        right_dot = Dot(axes.coords_to_point(0, 1), color=GREEN)
        label = MathTex(r"\lim_{x \to 0^-} \neq \lim_{x \to 0^+}").to_edge(UP)

        self.play(Create(axes), Create(graph))
        self.play(FadeIn(left_dot), FadeIn(right_dot), Write(label))
        self.wait(2)
